     6	type ActionState = { error?: string; message?: string };
     7	const initial: ActionState = {};
     8	
     9	function Notice({ state }: { state: ActionState }) {
    10	  if (state.error)
    11	    return <p className="text-xs font-medium text-red-400">{state.error}</p>;
    12	  if (state.message)
    13	    return <p className="text-xs font-medium text-emerald-400">{state.message}</p>;
    14	  return null;
    15	}
