    17	/**
    18	 * Refund a customer. Routes back to the original Stripe card when the payment
    19	 * can be traced, otherwise performs a wallet-only refund (see server action).
    20	 */
    21	export function RefundForm({
    22	  userId,
    23	  defaultAmount,
    24	}: {
    25	  userId: string;
    26	  defaultAmount?: number;
    27	}) {
    28	  const [state, action, pending] = useActionState(refundPayment, initial);
    29	  return (
    30	    <form action={action} className="space-y-3">
    31	      <input type="hidden" name="userId" value={userId} />
    32	      <div className="flex flex-wrap items-end gap-2">
    33	        <div>
    34	          <label className="label">Amount (USD)</label>
    35	          <input
    36	            className="input w-32 py-1.5"
    37	            name="amount"
    38	            type="number"
    39	            step="0.01"
    40	            min="0.01"
    41	            placeholder="0.00"
    42	            defaultValue={defaultAmount != null ? (defaultAmount / 100).toFixed(2) : undefined}
    43	            required
    44	          />
    45	        </div>
    46	        <div className="flex-1 min-w-[180px]">
    47	          <label className="label">Reason (optional)</label>
    48	          <input className="input w-full py-1.5" name="reason" type="text" placeholder="Duplicate charge…" maxLength={200} />
    49	        </div>
    50	        <button className="btn-danger py-1.5" disabled={pending}>
    51	          {pending ? "Refunding…" : "Refund"}
    52	        </button>
    53	      </div>
    54	      <Notice state={state} />
    55	      <p className="text-xs text-slate-500">
    56	        Refunds the original Stripe card when the payment is traceable, otherwise credits back the wallet.
    57	      </p>
    58	    </form>
    59	  );
    60	}
    61	
    62	/**
    63	 * Manual +/- wallet balance adjustment. Positive credits, negative debits
    64	 * (negative is the one case allowed to push a balance below zero).
    65	 */
    66	export function AdjustBalanceForm({ userId }: { userId: string }) {
    67	  const [state, action, pending] = useActionState(adjustBalance, initial);
    68	  return (
    69	    <form action={action} className="space-y-3">
    70	      <input type="hidden" name="userId" value={userId} />
    71	      <div className="flex flex-wrap items-end gap-2">
    72	        <div>
    73	          <label className="label">Adjustment (USD)</label>
    74	          <input
    75	            className="input w-32 py-1.5"
