    86	        </div>
    87	        <button className="btn-secondary py-1.5" disabled={pending}>
    88	          {pending ? "Applying…" : "Apply"}
    89	        </button>
    90	      </div>
    91	      <Notice state={state} />
    92	      <p className="text-xs text-slate-500">Use a negative amount to debit (e.g. clawing back a mistaken credit).</p>
