    95	}
    96	
    97	/** Both finance tools grouped in one card body, bound to a single customer. */
    98	export function RefundControls({
    99	  userId,
   100	  defaultAmount,
   101	}: {
   102	  userId: string;
   103	  defaultAmount?: number;
   104	}) {
   105	  return (
   106	    <div className="space-y-6">
   107	      <div>
   108	        <p className="section-label mb-2">Refund a payment</p>
