     1	"use client";
     2	
     3	import { useMemo, useState, useTransition } from "react";
     4	import { useRouter } from "next/navigation";
     5	import type { ReactNode } from "react";
     6	
     7	export type BulkColumn = { header: ReactNode; className?: string };
     8	export type BulkRow = { id: string; cells: ReactNode[]; selectable?: boolean };
     9	export type BulkAction = {
    10	  label: string;
    11	  /** Server action invoked with the selected row ids. */
    12	  run: (ids: string[]) => Promise<unknown>;
    13	  /** Confirmation prompt shown before running (skip when omitted). */
    14	  confirm?: string;
    15	  danger?: boolean;
    16	};
    17	
    18	/**
    19	 * A self-contained, selectable admin table. The parent (a Server Component)
    20	 * maps its data into `columns` + `rows` (cells may be arbitrary React nodes such
    21	 * as <Link>s) and passes an `exportHref` and optional bulk `actions`. Selection
    22	 * state, the select-all header checkbox and the floating action bar all live
    23	 * here on the client; the export link points at the CSV route.
    24	 */
    25	export function BulkTable({
    26	  columns,
    27	  rows,
    28	  exportHref,
    29	  actions = [],
    30	  minWidth = 720,
    31	  empty = "Nothing to show.",
    32	}: {
    33	  columns: BulkColumn[];
    34	  rows: BulkRow[];
    35	  exportHref?: string;
    36	  actions?: BulkAction[];
    37	  minWidth?: number;
    38	  empty?: string;
    39	}) {
    40	  const router = useRouter();
    41	  const [selected, setSelected] = useState<Set<string>>(new Set());
    42	  const [pending, start] = useTransition();
    43	  const [msg, setMsg] = useState<string | null>(null);
    44	
    45	  const selectableIds = useMemo(
    46	    () => rows.filter((r) => r.selectable !== false).map((r) => r.id),
    47	    [rows]
    48	  );
    49	  const allSelected = selectableIds.length > 0 && selectableIds.every((id) => selected.has(id));
    50	  const someSelected = selected.size > 0;
    51	
    52	  const toggle = (id: string) =>
    53	    setSelected((prev) => {
    54	      const next = new Set(prev);
    55	      next.has(id) ? next.delete(id) : next.add(id);
    56	      return next;
    57	    });
    58	
    59	  const toggleAll = () =>
    60	    setSelected(allSelected ? new Set() : new Set(selectableIds));
    61	
    62	  const runAction = (action: BulkAction) => {
    63	    if (action.confirm && !window.confirm(action.confirm)) return;
    64	    const ids = [...selected];
    65	    setMsg(null);
    66	    start(async () => {
    67	      try {
    68	        await action.run(ids);
    69	        setSelected(new Set());
    70	        setMsg(`${action.label}: ${ids.length} row${ids.length === 1 ? "" : "s"} done.`);
    71	        router.refresh();
    72	      } catch (e) {
    73	        setMsg(e instanceof Error ? e.message : "Action failed");
    74	      }
    75	    });
    76	  };
    77	
    78	  return (
    79	    <div>
    80	      {/* Action bar */}
    81	      <div className="flex flex-wrap items-center justify-between gap-3 px-5 pt-5">
    82	        <div className="flex items-center gap-3 text-sm text-slate-400">
    83	          <span>
    84	            {someSelected ? (
    85	              <span className="font-medium text-slate-200">{selected.size} selected</span>
    86	            ) : (
    87	              `${rows.length} row${rows.length === 1 ? "" : "s"}`
    88	            )}
    89	          </span>
    90	          {msg && <span className="text-xs text-slate-500">{msg}</span>}
    91	        </div>
    92	        <div className="flex flex-wrap items-center gap-2">
    93	          {someSelected &&
    94	            actions.map((a) => (
    95	              <button
    96	                key={a.label}
    97	                className={`${a.danger ? "btn-danger" : "btn-secondary"} py-1.5`}
    98	                disabled={pending}
    99	                onClick={() => runAction(a)}
   100	              >
   101	                {a.label}
   102	                <span className="ml-1 opacity-70">({selected.size})</span>
   103	              </button>
   104	            ))}
   105	          {exportHref && (
   106	            <a className="btn-secondary py-1.5" href={exportHref}>
   107	              Export CSV
   108	            </a>
   109	          )}
   110	        </div>
   111	      </div>
   112	
   113	      {rows.length === 0 ? (
   114	        <p className="px-5 py-10 text-center text-sm text-slate-500">{empty}</p>
   115	      ) : (
   116	        <div className="overflow-x-auto pt-3">
   117	          <table className="table-shell" style={{ minWidth }}>
   118	            <thead>
   119	              <tr>
   120	                <th className="w-10">
   121	                  <input
   122	                    type="checkbox"
   123	                    aria-label="Select all"
   124	                    checked={allSelected}
   125	                    onChange={toggleAll}
   126	                    disabled={selectableIds.length === 0}
   127	                  />
   128	                </th>
