"use server";

import { z } from "zod";
import { revalidatePath } from "next/cache";
import { headers } from "next/headers";
import type { Coupon } from "@prisma/client";
import { db } from "./db";
import { requireUser, requireAdmin, realUser } from "./auth";
import { getSettingBool, getSettingInt } from "./settings";

/**
 * Internal-only guard for the growth credit functions below.
 *
 * `grantSignupCredit` / `maybeRewardReferral` are exported from this "use server"
 * module, so Next.js registers them as callable action endpoints that would
 * otherwise let anyone POST a raw `userId` and mint signup/referral credit. Their
 * only legitimate callers invoke them internally: the register / topUp /
 * orderServer server actions, the order-placement flow, and the Stripe webhook
 * route. A direct client POST to an action carries the `next-action` header;
 * server-to-server route/webhook calls do not. So: when the invocation arrives
 * through the action dispatcher, only allow it when the real signed-in account is
 * acting on its OWN userId (an attacker cannot then target another account);
 * non-action server contexts (e.g. the Stripe webhook) are allowed through.
 */
async function assertInternalGrowthCaller(userId: string): Promise<void> {
  const h = await headers();
  if (!h.has("next-action")) return; // route handler / webhook / internal call
  const real = await realUser();
  if (!real || real.id !== userId) throw new Error("FORBIDDEN");
}
import {
  describeCoupon,
  referralRewardCents,
  signupFreeCreditCents,
  type CouponApplyResult,
} from "./growth";

// ---------- Coupons ----------

/**
 * Compute the extra wallet credit a coupon grants for a top-up of `baseCents`.
 * PERCENT -> baseCents * value%; FIXED_CENTS / CREDIT_CENTS -> flat `value` cents.
 */
function couponBonusForTopup(coupon: Coupon, baseCents: number): number {
  switch (coupon.kind) {
    case "PERCENT":
      return Math.round((baseCents * coupon.value) / 100);
    case "FIXED_CENTS":
    case "CREDIT_CENTS":
      return coupon.value;
    default:
      return 0;
  }
}

/**
 * Validate a promo code for the CURRENT user against a top-up of `baseCents` and
 * return the bonus that would be credited. Read-only: it never mutates state,
 * so it is safe to call both for the live preview (CouponField) and again inside
 * `topUp` to compute the real bonus. Enforces active / expiry / scope /
 * minAmount / maxRedemptions / firstTimeOnly / one-per-user rules.
 */
export async function applyCouponToTopup(
  code: string,
  baseCents: number
): Promise<CouponApplyResult> {
  const user = await requireUser();
  // Global kill-switch: when coupons are disabled no code may be redeemed.
  // Checked here so both the live preview and the real `topUp` apply are covered.
  if (!(await getSettingBool("coupons_enabled", true))) {
    return { ok: false, error: "Promo codes are currently disabled." };
  }
  const normalized = String(code ?? "").trim().toUpperCase();
  if (!normalized) return { ok: false, error: "Enter a promo code." };

  const coupon = await db.coupon.findUnique({ where: { code: normalized } });
  if (!coupon || !coupon.active) return { ok: false, error: "That code isn’t valid." };
  if (coupon.scope === "ORDER") {
    return { ok: false, error: "This code only applies to server orders." };
  }
  if (coupon.expiresAt && coupon.expiresAt.getTime() < Date.now()) {
    return { ok: false, error: "This code has expired." };
  }
  if (coupon.maxRedemptions !== null && coupon.timesRedeemed >= coupon.maxRedemptions) {
    return { ok: false, error: "This code has reached its redemption limit." };
  }
  if (coupon.minAmountCents !== null && baseCents < coupon.minAmountCents) {
    return {
      ok: false,
      error: `Add at least $${(coupon.minAmountCents / 100).toFixed(2)} to use this code.`,
    };
  }

  // One redemption per user (mirrors the @@unique([couponId,userId]) constraint).
  const already = await db.couponRedemption.findUnique({
    where: { couponId_userId: { couponId: coupon.id, userId: user.id } },
  });
  if (already) return { ok: false, error: "You’ve already used this code." };

  if (coupon.firstTimeOnly) {
    // "First-time" = the user has never received a positive wallet credit before.
    const priorCredits = await db.walletTransaction.count({
      where: { userId: user.id, amountCents: { gt: 0 } },
    });
    if (priorCredits > 0) {
      return { ok: false, error: "This code is for first-time customers only." };
    }
  }

  const bonusCents = Math.max(0, couponBonusForTopup(coupon, baseCents));
  return {
    ok: true,
    couponId: coupon.id,
    code: coupon.code,
    bonusCents,
    label: describeCoupon(coupon),
  };
}

// ---------- Admin: coupon management ----------

const couponSchema = z.object({
  code: z
    .string()
    .trim()
    .min(3)
    .max(32)
    .regex(/^[A-Za-z0-9_-]+$/, "Code: letters, digits, dashes/underscores only."),
  kind: z.enum(["PERCENT", "FIXED_CENTS", "CREDIT_CENTS"]),
  scope: z.enum(["ANY", "TOPUP", "ORDER"]),
  value: z.coerce.number().int().min(1).max(1_000_000),
  firstTimeOnly: z.coerce.boolean(),
  minAmountCents: z.coerce.number().int().min(0).max(10_000_000).optional(),
  maxRedemptions: z.coerce.number().int().min(1).max(1_000_000).optional(),
  expiresAt: z.string().optional(),
  note: z.string().max(200).optional(),
});

