"use client";

import { useMemo, useState } from "react";

export type DocSection = {
  id: string;
  title: string;
  /** Pre-rendered, sanitized HTML for this section. */
  html: string;
  /** Lowercased plain text, for the client-side filter. */
  search: string;
};

/**
 * Renders the pre-sanitized documentation sections with a client-side filter
 * box. The markdown is rendered to safe HTML on the server (see lib/markdown.ts)
 * — this component only shows/hides sections, it never re-parses source.
 */
export function DocsViewer({ sections }: { sections: DocSection[] }) {
  const [q, setQ] = useState("");
  const query = q.trim().toLowerCase();

  const visible = useMemo(
    () => (query ? sections.filter((s) => s.search.includes(query)) : sections),
    [sections, query]
  );

  return (
    <div className="space-y-6">
      <div className="sticky top-16 z-10 -mx-1 bg-navy-950/80 px-1 py-2 backdrop-blur">
        <input
          className="input w-full py-2.5"
          type="search"
          value={q}
          onChange={(e) => setQ(e.target.value)}
          placeholder="Search the documentation…"
        />
        {query && (
          <p className="mt-2 text-xs text-slate-500">
            {visible.length} section{visible.length === 1 ? "" : "s"} match “{q}”.
          </p>
        )}
      </div>

      {visible.length === 0 ? (
        <div className="card py-12 text-center text-sm text-slate-400">
          No documentation sections match “{q}”.
        </div>
      ) : (
        <div className="card space-y-3 p-6">
          {visible.map((s) => (
            <section
              key={s.id}
              className="prose-invert space-y-3 [&_h2]:scroll-mt-24"
              dangerouslySetInnerHTML={{ __html: s.html }}
            />
          ))}
        </div>
      )}
    </div>

