export type RenderedEmail = { subject: string; html: string; template: string };

/**
 * Render a stored (or default) template for `key`, substituting `vars`,
 * returning the final subject and full wrapped HTML ready to send/preview.
 */
export async function renderTemplate(key: string, vars: Record<string, unknown> = {}): Promise<RenderedEmail> {
  let subject: string;
  let body: string;

  let row: { subject: string; html: string; enabled: boolean } | null = null;
  try {
    row = await db.emailTemplate.findUnique({
      where: { key },
      select: { subject: true, html: true, enabled: true },
    });
  } catch {
    row = null;
  }

  if (row && row.enabled) {
    subject = row.subject;
    body = row.html;
  } else {
    const d = DEFAULTS[key] ?? GENERIC_FALLBACK(key);
    subject = d.subject;
    body = d.body;
  }

  const preheader = typeof vars.preheader === "string" ? (vars.preheader as string) : undefined;
  return {
    template: key,
    subject: substitute(subject, vars),
    html: wrapEmail(substitute(body, vars), { preheader }),
  };
}

/**
